def solve(g, marker, fill):
    R,C = len(g), len(g[0])
    out = [row[:] for row in g]
    for r in range(R):
        ps = [c for c in range(C) if g[r][c]==marker]
        if len(ps)>=2:
            for c in range(min(ps)+1, max(ps)):
                out[r][c]=fill
    for c in range(C):
        ps = [r for r in range(R) if g[r][c]==marker]
        if len(ps)>=2:
            for r in range(min(ps)+1, max(ps)):
                out[r][c]=fill
    return out

